import{_ as o,o as r,c as l,a2 as a}from"./chunks/framework.DnrXFDHb.js";const d=JSON.parse('{"title":"算力方舱赛道深度分析：客户需求与爆品设计方向","description":"","frontmatter":{"title":"算力方舱赛道深度分析：客户需求与爆品设计方向","updated":"2026-09-09T00:00:00.000Z","visibility":"public"},"headers":[],"relativePath":"算电协同/算力方舱赛道深度分析_客户需求与爆品设计方向.md","filePath":"算电协同/算力方舱赛道深度分析_客户需求与爆品设计方向.md","lastUpdated":1789119850000}'),i={name:"算电协同/算力方舱赛道深度分析_客户需求与爆品设计方向.md"};function n(s,t,e,u,q,h){return r(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="算力方舱赛道深度分析-客户需求、客户价值与爆品设计方向" tabindex="-1">算力方舱赛道深度分析：客户需求、客户价值与爆品设计方向 <a class="header-anchor" href="#算力方舱赛道深度分析-客户需求、客户价值与爆品设计方向" aria-label="Permalink to &quot;算力方舱赛道深度分析：客户需求、客户价值与爆品设计方向&quot;">​</a></h1><p><strong>——给寰晟电力合作伙伴体系的产品设计输入</strong></p><blockquote><p>版本：V1.0｜2026-09-09 性质：内部产品战略研究。文中市场数据均标注来源与时点，测算均为示意性测算（非收益承诺）。 注意：涉及合资公司（3H 能算科技）与在途业务的表述仅作内部讨论，不对外。</p></blockquote><hr><h2 id="一、先说核心判断" tabindex="-1">一、先说核心判断 <a class="header-anchor" href="#一、先说核心判断" aria-label="Permalink to &quot;一、先说核心判断&quot;">​</a></h2><p><strong>核心判断：算力方舱现在的&quot;百花齐放、没有标准&quot;，不是这个赛道的混乱期，而是标准定义权的窗口期。但这个窗口期里，90% 的玩家在做同一件事——把服务器装进箱子；真正稀缺的，是把&quot;电&quot;作为第一性原理来设计的方舱。客户最终不为箱子付费，而为四样东西付费：时间（多快上线）、电（多便宜多稳）、确定性（出不出事）、进退自由（资产能不能搬走、能不能扩容、残值几何）。寰晟的 HVDC 电力电子积累 + 重卡超充集装箱的户外电力工程化能力，恰好长在这四个价值点中最硬的那个——电。这决定了我们的方舱不应该是&quot;又一个集装箱机房&quot;，而应该是&quot;电力原生的算力基础设施&quot;。</strong></p><p>次级判断一：<strong>方舱的需求结构正在被&quot;推理下沉&quot;重塑。</strong> IDC 数据显示 2026 年推理算力占智能算力比重将升至 62.2%（烽火通信援引，2025-10）；Gartner 预测到 2028 年全球推理消耗的算力将是训练的 3 倍。训练向西部枢纽集中，推理向用户身边下沉——边缘节点、园区、县域、场站，这些点位不可能土建机房，天然是方舱的场景。</p><p>次级判断二：<strong>算力是&quot;低端过剩、高端紧缺&quot;的结构性市场，方舱恰好卡在结构转换带上。</strong> 2026 年上半年国内 AI 算力需求同比增长 417%，高端 GPU 月租站稳 5.5-6.6 万元、新签订单排到 2027 年上半年；另一边是大量低密通用算力上架率不足 30%。客户买的不再是&quot;算力有无&quot;，而是&quot;上架速度和运营效率&quot;——这正是预制化方舱相对土建机房的差异点。</p><p>次级判断三：<strong>方舱的终局竞争不在箱体，在&quot;电网友好度&quot;。</strong> 南方电网已把移动算力方舱做成&quot;电网调度牌&quot;——用价格信号指挥方舱什么时候算、什么时候停，并把每度电的碳足迹做成可交易的碳资产（36 氪，2026-06）。零碳园区政策 2026 年进入实质落地期。只会耗电的方舱是成本中心，会跟电网做交易的方舱是利润中心。这是所有箱体厂、甚至大部分设备商都还没补上的课，恰是我们的主场。</p><hr><h2 id="二、赛道扫描-三类玩家、三个共识、一个空位" tabindex="-1">二、赛道扫描：三类玩家、三个共识、一个空位 <a class="header-anchor" href="#二、赛道扫描-三类玩家、三个共识、一个空位" aria-label="Permalink to &quot;二、赛道扫描：三类玩家、三个共识、一个空位&quot;">​</a></h2><h3 id="_2-1-三类玩家在做什么" tabindex="-1">2.1 三类玩家在做什么 <a class="header-anchor" href="#_2-1-三类玩家在做什么" aria-label="Permalink to &quot;2.1 三类玩家在做什么&quot;">​</a></h3><table tabindex="0"><thead><tr><th>玩家类型</th><th>代表</th><th>打法</th><th>软肋</th></tr></thead><tbody><tr><td>云厂/ICT 巨头</td><td>阿里云 CUBE 5.0、华为 FusionDC、烽火液冷 POD</td><td>全栈方案、90% 预制化、100 天交付、自研芯片绑定、出海认证</td><td>绑定自家生态，服务超大客户；不碰几百 kW 的&quot;小散偏&quot;点位</td></tr><tr><td>电源/温控/能源装备厂</td><td>台达（COMPUTEX 2026 预制 AI 模块数据中心，部署时间缩短 60%）、维谛、杰瑞（五大模块舱+燃气发电一体化，北美订单超 11 亿美元）</td><td>从供配电/温控强项向整舱集成延伸</td><td>强在 MW 级大项目，弱在分散场景的快速复制与渠道</td></tr><tr><td>箱体/集成商</td><td>各地集装箱厂（15-80 万/台低端箱体到 80-300 万含液冷方舱）</td><td>便宜、快、定制灵活</td><td>无电力电子内核，PUE、可靠性、电力合规全靠外采拼装，本质是&quot;装修队&quot;</td></tr></tbody></table><h3 id="_2-2-市场已形成的三个共识" tabindex="-1">2.2 市场已形成的三个共识 <a class="header-anchor" href="#_2-2-市场已形成的三个共识" aria-label="Permalink to &quot;2.2 市场已形成的三个共识&quot;">​</a></h3><ol><li><strong>预制化是明确方向。</strong> 华为预制模块化数据中心连续十年全球第一（华为官方，2024-12）；阿里云 CUBE 5.0 模块化率从 30% 提到 90%，100 天完整交付，风冷 PUE≤1.15、液冷≤1.10，且已拿到欧洲 CE、东南亚 IEC 准入，2026 年产能计划提升两倍以上（搜狐科技实地探访，2026-08）。交付速度和能效已经是牌桌上的入场券，不是差异化。</li><li><strong>供电架构正在代际切换。</strong> 英伟达 2025 年 10 月发布 800V HVDC 白皮书，明确&quot;交流 UPS → 800V HVDC → SST/中压整流器&quot;路线，2027 年起随 Kyber 机架全面投产。HVDC 供电效率 96%-98%，比传统 UPS（92%-94%）高出一个台阶，占地减少 30% 以上。<strong>这意味着：今天新设计的方舱如果还是交流 UPS 架构，出厂就是上一代产品。</strong></li><li><strong>&quot;能源一体化&quot;成为 AIDC 下半场主线。</strong> 杰瑞等能源装备企业用&quot;发电+储能+液冷&quot;整舱方案切北美市场（界面新闻/同花顺，2026-07/08），行业共识是：能源承载能力不再是配套，而是决定算力部署上限和商业可行性的底层架构。</li></ol><h3 id="_2-3-那个空位" tabindex="-1">2.3 那个空位 <a class="header-anchor" href="#_2-3-那个空位" aria-label="Permalink to &quot;2.3 那个空位&quot;">​</a></h3><p>巨头做 MW 级、绑定自家云生态；箱体厂做壳子、不懂电；电源厂做标准品、不下沉。<strong>没有人认真做&quot;电力原生的、100kW-2MW 级的、电网友好的分布式算力方舱&quot;</strong>——而这个功率段，恰好覆盖推理下沉、县域智算、园区、场站这些增长最快、巨头看不上、箱体厂做不了的市场。这就是我们的生态位。</p><hr><h2 id="三、谁在买方舱-六类客户的需求深拆" tabindex="-1">三、谁在买方舱：六类客户的需求深拆 <a class="header-anchor" href="#三、谁在买方舱-六类客户的需求深拆" aria-label="Permalink to &quot;三、谁在买方舱：六类客户的需求深拆&quot;">​</a></h2><blockquote><p>方法说明：以下按&quot;场景—痛点—决策链—付费逻辑—价值锚点&quot;拆解。价值锚点是产品设计的输入。</p></blockquote><h3 id="_3-1-推理下沉型客户-政企、医院、工厂、园区" tabindex="-1">3.1 推理下沉型客户（政企、医院、工厂、园区） <a class="header-anchor" href="#_3-1-推理下沉型客户-政企、医院、工厂、园区" aria-label="Permalink to &quot;3.1 推理下沉型客户（政企、医院、工厂、园区）&quot;">​</a></h3><ul><li><strong>场景</strong>：数据不出域的本地化推理——政务大模型、医疗影像、工业质检、园区安防。边缘计算节点县域覆盖率不足 20%（2026-05 行业方案数据），缺口真实存在。</li><li><strong>痛点</strong>：自建机房要过能评、消防、环评，周期一年以上；租云又怕数据出域。</li><li><strong>决策链</strong>：信息化部门提需求 → 一把手拍板 → 财政/预算约束极硬。</li><li><strong>付费逻辑</strong>：项目制，预算有限，对&quot;交钥匙+合规手续代办&quot;极度敏感。</li><li><strong>价值锚点</strong>：<strong>合规确定性 + 即插即用</strong>。方舱要把能评、消防、数据安全的&quot;合规包&quot;做成标准交付物。</li></ul><h3 id="_3-2-县域-普惠算力客户-地方政府、城投、县域运营商" tabindex="-1">3.2 县域/普惠算力客户（地方政府、城投、县域运营商） <a class="header-anchor" href="#_3-2-县域-普惠算力客户-地方政府、城投、县域运营商" aria-label="Permalink to &quot;3.2 县域/普惠算力客户（地方政府、城投、县域运营商）&quot;">​</a></h3><ul><li><strong>场景</strong>：县域智算中心，承接&quot;东数西算&quot;末梢与本地产业 AI 化。</li><li><strong>痛点</strong>：缺技术、缺运维、缺订单——建得起养不起，上架率是生死线（行业普遍不足 30% 的利用率是前车之鉴）。</li><li><strong>决策链</strong>：政府招商逻辑，重&quot;投资强度+税收+就业&quot;叙事。</li><li><strong>付费逻辑</strong>：需要&quot;产品+运营&quot;打包，甚至要求带算力订单进县。</li><li><strong>价值锚点</strong>：<strong>可运营性</strong>。卖舱只是开始，客户要的是&quot;能算得起来、租得出去&quot;。（这与恒密算力的订单赋能能力天然咬合。）</li></ul><h3 id="_3-3-绿电直连-源网荷储客户-新能源场站、零碳园区" tabindex="-1">3.3 绿电直连/源网荷储客户（新能源场站、零碳园区） <a class="header-anchor" href="#_3-3-绿电直连-源网荷储客户-新能源场站、零碳园区" aria-label="Permalink to &quot;3.3 绿电直连/源网荷储客户（新能源场站、零碳园区）&quot;">​</a></h3><ul><li><strong>场景</strong>：风光场站就地消纳、零碳园区配套算力。南网模式已验证：电价低时多算、高时少算，碳足迹可追溯可交易（2025 年全国碳市场成交 8.65 亿吨、576 亿元）。</li><li><strong>痛点</strong>：绿电波动性与算力连续性矛盾；并网容量批不下。</li><li><strong>付费逻辑</strong>：算的是综合能源账——消纳收益+算力收益+碳资产。</li><li><strong>价值锚点</strong>：<strong>电网友好度</strong>。方舱必须是&quot;可调负荷&quot;，原生支持功率调节与调度接口。</li></ul><h3 id="_3-4-充算一体客户-重卡超充站、物流园、高速服务区-★独家赛道" tabindex="-1">3.4 充算一体客户（重卡超充站、物流园、高速服务区）★独家赛道 <a class="header-anchor" href="#_3-4-充算一体客户-重卡超充站、物流园、高速服务区-★独家赛道" aria-label="Permalink to &quot;3.4 充算一体客户（重卡超充站、物流园、高速服务区）★独家赛道&quot;">​</a></h3><ul><li><strong>场景</strong>：重卡超充站普遍按峰值配变压器（兆瓦级容量），但充电负荷白天集中、夜间闲置，容量利用率常年只有 25%-35%。</li><li><strong>痛点</strong>：交了容量电费、占了并网指标，资产大半时间在睡觉。</li><li><strong>付费逻辑</strong>：<strong>同一份并网容量，白天超充、夜间算力填谷，一份资产两份收入</strong>。示意测算：2MW 站点叠加 500kW 算力方舱（PUE 1.15、负载率 65%），年耗电约 327 万度，可把站点容量利用率从约 30% 抬到约 50% 量级。</li><li><strong>价值锚点</strong>：<strong>容量复用率</strong>。这是寰晟重卡超充集装箱基因的直接延伸——全球范围内几乎没人在这个交叉点上做产品。</li></ul><h3 id="_3-5-应急-特种-移动客户-矿区、海岛、野外作业、应急保障" tabindex="-1">3.5 应急/特种/移动客户（矿区、海岛、野外作业、应急保障） <a class="header-anchor" href="#_3-5-应急-特种-移动客户-矿区、海岛、野外作业、应急保障" aria-label="Permalink to &quot;3.5 应急/特种/移动客户（矿区、海岛、野外作业、应急保障）&quot;">​</a></h3><ul><li><strong>场景</strong>：矿山无人驾驶本地推理、海上平台、野外勘探、灾害应急通信+算力。</li><li><strong>痛点</strong>：无市电或弱电网、高震动、高盐雾、无人值守。</li><li><strong>付费逻辑</strong>：对价格不敏感，对可靠性和环境适应极端敏感。</li><li><strong>价值锚点</strong>：<strong>环境适应 + 无人值守</strong>。重卡超充集装箱的户外三防、车载抗震工程经验直接可迁移。</li></ul><h3 id="_3-6-出海客户-中东、东南亚、非洲" tabindex="-1">3.6 出海客户（中东、东南亚、非洲） <a class="header-anchor" href="#_3-6-出海客户-中东、东南亚、非洲" aria-label="Permalink to &quot;3.6 出海客户（中东、东南亚、非洲）&quot;">​</a></h3><ul><li><strong>场景</strong>：电网弱、基建慢、高温高湿，但 AI 需求爆发。阿里云、台达都在拿 CE/IEC 认证往外走，杰瑞用燃气发电+液冷整舱切中东。</li><li><strong>痛点</strong>：当地没有施工能力，需要&quot;工厂造好、拉过去就能跑&quot;。</li><li><strong>价值锚点</strong>：<strong>交钥匙 + 认证 + 离网/弱网适配</strong>（可配柴发/燃气/储能接口）。</li></ul><hr><h2 id="四、客户价值的底层公式-客户买的不是箱子-是四样东西" tabindex="-1">四、客户价值的底层公式：客户买的不是箱子，是四样东西 <a class="header-anchor" href="#四、客户价值的底层公式-客户买的不是箱子-是四样东西" aria-label="Permalink to &quot;四、客户价值的底层公式：客户买的不是箱子，是四样东西&quot;">​</a></h2><p><strong>价值一：时间。</strong> 算力租金是计时收入，晚一天上线就是一天的现金流损失。土建机房 12-18 个月 vs 预制方舱 3-4 个月（阿里口径 100 天），在高端算力紧缺窗口期，时间价值可以直接折算成租金收入。<strong>设计含义：交付周期必须写进产品规格书，作为核心卖点承诺。</strong></p><p><strong>价值二：电。</strong> 电费是运营成本主项。以一个 500kW IT 负荷方舱（负载率 65%、电价 0.6 元/度）示意测算：</p><ul><li>PUE 1.4 → 1.15，年省电费约 43 万元，<strong>十年就是一台方舱的钱</strong>（约 430 万）；</li><li>供电链路从 UPS（92%）换到 HVDC（96.5%）再到 SST/巴拿马（98.5%），年供电损耗从约 25 万度降到 4 万度——<strong>效率每提升一个点，都是客户十年的现金流</strong>；</li><li>若方舱作为可调负荷参与电力现货，按日转移 690 度、峰谷价差 0.4 元示意，年增收约 10 万元/舱——单舱不多，但这是&quot;从耗电到赚电&quot;的物种差异，且 100 个舱组网接入虚拟电厂就是千万级。</li></ul><p><strong>设计含义：PUE、供电效率、可调负荷接口，是报价单之外的第二份报价单。</strong></p><p><strong>价值三：确定性。</strong> 宕机、过热、供电中断对推理业务是致命伤。确定性=供电冗余+热管理冗余+远程可运维。<strong>设计含义：无人值守能力（远程监控、模块热插拔、故障自隔离）决定方舱能不能规模化铺到没人愿意去的地方。</strong></p><p><strong>价值四：进退自由。</strong> 方舱本质是&quot;会走的算力资产&quot;——可迁移（跟着电价和订单走）、可扩容（乐高式加舱）、有残值（二手流转）。这是固定资产视角下最被低估的价值：土建机房砸下去就是沉没成本，方舱保留了资产的流动性。<strong>设计含义：标准化接口 + 模块化功率档位，让&quot;加舱&quot;和&quot;搬舱&quot;成为产品级能力，而不是工程级项目。</strong></p><hr><h2 id="五、我们的差异化定位-电力原生-power-native-算力方舱" tabindex="-1">五、我们的差异化定位：电力原生（Power-Native）算力方舱 <a class="header-anchor" href="#五、我们的差异化定位-电力原生-power-native-算力方舱" aria-label="Permalink to &quot;五、我们的差异化定位：电力原生（Power-Native）算力方舱&quot;">​</a></h2><p>一句定位语：<strong>&quot;别人是箱子里装算力，我们是电力系统里长算力。&quot;</strong></p><p>三个别人抄不走的禀赋：</p><ol><li><strong>HVDC 电力电子内核。</strong> 供电链路是方舱里技术含量最高、对客户 TCO 影响最深的部分。寰晟的 HVDC 能力让我们能做&quot;直流原生&quot;方舱：当前 240/336V HVDC 主供（效率 96.5%+），架构上预留 800V 演进路径——英伟达 800V 生态 2026 年起逐步商用、2027 年放量，届时客户在舱内换侧挂电源（Sidecar）即可升级，箱体与配电不报废。<strong>把&quot;不落伍&quot;设计成产品属性。</strong></li><li><strong>重卡超充集装箱的户外工程化平台。</strong> 三防、抗震、热管理、高功率电力电子的集装箱集成，是已量产验证的能力，研发成本和周期大幅低于从零起步。</li><li><strong>&quot;充+储+算&quot;一体场景独占。</strong> 超充站网络是现成的渠道与场景入口，充算一体舱是我们能定义、别人难跟随的品类。</li></ol><h2 id="六、爆品设计方向" tabindex="-1">六、爆品设计方向 <a class="header-anchor" href="#六、爆品设计方向" aria-label="Permalink to &quot;六、爆品设计方向&quot;">​</a></h2><h3 id="方向一-电力原生架构——把-电-从配套做成主卖点" tabindex="-1">方向一：电力原生架构——把&quot;电&quot;从配套做成主卖点 <a class="header-anchor" href="#方向一-电力原生架构——把-电-从配套做成主卖点" aria-label="Permalink to &quot;方向一：电力原生架构——把&quot;电&quot;从配套做成主卖点&quot;">​</a></h3><ul><li>供电链全直流：10kV 进舱 → HVDC 直供机柜，砍掉 UPS 多级变换；</li><li>800V-ready 预留：舱体电气空间、母线、连接器按 800V 演进预留；</li><li>储能一体：舱内/舱侧储能既做备电（替代柴发），又做负荷平移（参与现货与需求响应）；</li><li>交付物里放一张&quot;电力白皮书&quot;：每个舱实测 PUE、供电效率、年电费测算——用数字卖舱。</li></ul><h3 id="方向二-充算储一体舱——爆品楔子-建议优先" tabindex="-1">方向二：充算储一体舱——爆品楔子（建议优先） <a class="header-anchor" href="#方向二-充算储一体舱——爆品楔子-建议优先" aria-label="Permalink to &quot;方向二：充算储一体舱——爆品楔子（建议优先）&quot;">​</a></h3><ul><li>产品定义：与重卡超充站共站部署的标准方舱，共享变压器容量与并网户头，内置功率调度控制器（充电高峰时限算力功率，夜间算力满发）；</li><li>客户一句话价值：<strong>&quot;一座站，两份收入，并网容量不浪费&quot;</strong>；</li><li>竞争空白：云厂不下场、箱体厂不懂电、电源厂没有超充场景。这是我们最有机会打出&quot;品类第一&quot;的楔子。</li></ul><h3 id="方向三-电网友好型——让方舱成为-会赚钱的负荷" tabindex="-1">方向三：电网友好型——让方舱成为&quot;会赚钱的负荷&quot; <a class="header-anchor" href="#方向三-电网友好型——让方舱成为-会赚钱的负荷" aria-label="Permalink to &quot;方向三：电网友好型——让方舱成为&quot;会赚钱的负荷&quot;&quot;">​</a></h3><ul><li>原生支持需求响应/虚拟电厂/现货价差调度三类接口（对标南网模式，但我们做成标准产品而非定制项目）；</li><li>舱级 EMS 与算力调度联动：电价信号 → 推理任务排队/降频/迁移；</li><li>碳足迹计量模块：每度电的碳排可溯，为零碳园区客户输出碳资产台账。</li></ul><h3 id="方向四-标准化-sku——在-无标准-窗口期抢定义权" tabindex="-1">方向四：标准化 SKU——在&quot;无标准&quot;窗口期抢定义权 <a class="header-anchor" href="#方向四-标准化-sku——在-无标准-窗口期抢定义权" aria-label="Permalink to &quot;方向四：标准化 SKU——在&quot;无标准&quot;窗口期抢定义权&quot;">​</a></h3><p>百花齐放无标准，恰恰是谁先定标准谁收割市场的窗口（类比地产当年的精装交付标准之争）。建议：</p><ul><li>定义三个功率密度档位与两类散热形态的标准接口（电气/水路/网络/吊装），形成自有产品标准 → 推动成团体标准；</li><li>产品矩阵收敛为三个 SKU，不做无边际定制： <ul><li><strong>S 级·充算储一体站舱</strong>（500kW-1MW，与超充站共站）——旗舰爆品；</li><li><strong>A 级·推理标准舱</strong>（300-500kW，HVDC+风液兼容，液冷 PUE≤1.15）——走量主力；</li><li><strong>B 级·边缘轻量舱</strong>（100-200kW，县域/园区/特种场景）——下沉尖刀。</li></ul></li></ul><h3 id="方向五-从卖舱到-舱-电-运营-——商业模式即护城河" tabindex="-1">方向五：从卖舱到&quot;舱+电+运营&quot;——商业模式即护城河 <a class="header-anchor" href="#方向五-从卖舱到-舱-电-运营-——商业模式即护城河" aria-label="Permalink to &quot;方向五：从卖舱到&quot;舱+电+运营&quot;——商业模式即护城河&quot;">​</a></h3><ul><li>县域客户怕养不起：捆绑恒密算力的订单与运维能力，提供&quot;代运营/算力代销&quot;选项；</li><li>电站客户算综合账：提供&quot;电费节约+现货收益+碳资产&quot;的 TCO 模型作为销售工具；</li><li>所有测算必须做敏感性分析（电价±0.1 元、负载率±15% 对回收期的影响），明示&quot;示意性测算不构成收益承诺&quot;——合规红线，也是专业信任的加分项。</li></ul><h2 id="七、路线图与风险红线" tabindex="-1">七、路线图与风险红线 <a class="header-anchor" href="#七、路线图与风险红线" aria-label="Permalink to &quot;七、路线图与风险红线&quot;">​</a></h2><p><strong>路线图（建议）</strong></p><ul><li>0-6 个月：S 级概念验证舱，选 1-2 个自有/合作超充站做示范，跑通&quot;共站并网+功率调度&quot;实测数据；</li><li>6-12 个月：A/B 级小批量，拿第三方认证（抗震、消防、防护等级、能效），形成实测&quot;电力白皮书&quot;；</li><li>12-24 个月：推动团体标准，启动出海认证（CE/IEC），S 级复制到站网。</li></ul><p><strong>风险红线</strong></p><ul><li>不碰低端箱体价格战（15-80 万价位段是红海，我们不在那里竞争）；</li><li>算力租赁价格波动与上架率风险：舱好卖 ≠ 客户赚钱，订单赋能能力必须前置，避免卖成&quot;一次性买卖&quot;；</li><li>合规：能评、消防、数据安全属地要求差异大，&quot;合规包&quot;需按区域版本化；</li><li>技术路线：800V 演进节奏存在不确定性（国内短期以混合架构为主），预留升级但不过度超前配置，控制 BOM 成本。</li></ul><h2 id="八、主要数据与测算依据" tabindex="-1">八、主要数据与测算依据 <a class="header-anchor" href="#八、主要数据与测算依据" aria-label="Permalink to &quot;八、主要数据与测算依据&quot;">​</a></h2><ol><li>IDC（烽火通信援引，2025-10）：2026 年推理算力占智能算力比重升至 62.2%；烽火液冷 POD 单机柜最高 58kW、单 POD 1024P@FP16。</li><li>阿里云 CUBE 5.0 实地探访（搜狐科技，2026-08）：模块化率 90%、100 天交付、风冷 PUE≤1.15/液冷≤1.10、标配高压直流、CE/IEC 认证、2026 年产能提升两倍以上。</li><li>华为数字能源（2024-12）：预制模块化数据中心连续十年全球第一；成都智算中心 TTM 缩短 50%。</li><li>英伟达 800V HVDC 白皮书及产业解读（OCP 2025-10；银河证券 2025-12）：UPS→800V HVDC→SST 路线，2027 年 Kyber 全面投产；HVDC 效率 96-98% vs UPS 92-94%，占地 -30%。</li><li>36 氪（2026-06）：南网移动算力方舱的电价调度与碳资产模式；2025 年全国碳市场成交 8.65 亿吨/576.33 亿元。</li><li>市场结构数据（2026 年 6 月）：国内 AI 算力需求同比 +417%，H100 月租 5.5-6.0 万元、H200 6.0-6.6 万元；低密通用算力上架率普遍不足 30%。</li><li>杰瑞 AIDC 一体化方案（界面新闻 2026-07 / 同花顺 2026-08）：五大模块舱全预制，北美燃气发电+液冷订单超 11 亿美元，TCO 降 25%+。</li><li>台达 COMPUTEX 2026：预制式 AI 模块化数据中心，部署时间缩短最高 60%。</li></ol><blockquote><p>测算说明：第四章全部数字为示意性测算（500kW IT 负荷、负载率 65%、电价 0.6 元/度、峰谷价差 0.4 元/度假设），仅供产品设计讨论，不构成任何收益承诺。</p></blockquote><hr><p><em>本文档为内部产品战略研究，含涉密主体信息，请勿外发。</em></p>',67)])])}const c=o(i,[["render",n]]);export{d as __pageData,c as default};
